export const VOICE_FILES={"אני: הלו? נועה? מה קרה כל כך מוקדם?": ["./assets/voices/voice171-23a1b2e9756d5a.mp3"], "נועה: בוקר טוב, אדם. היום אנחנו בודקים את הקורים של העכביש בתא שמונה. אנחנו מנסים לפתח חבלים חזקים שיעזרו לחלץ אנשים. אני צריכה אותך איתנו במעבדה.": ["./assets/voices/voice171-17213e62fa4c68.mp3"], "נועה: תלבש את בגדי העבודה, קח את התיק ואת תג העובד, וסע אלינו. הצוות כבר מתכונן. ואל תיגש לתא לפני שנבדוק שהזכוכית נעולה. נתראה בקרוב.": ["./assets/voices/voice171-3b4580c2a8bb2a.mp3"], "בוקר טוב! זה הבית שלך. אתה עובד כעוזר מחקר במעבדת העכבישים. היום הצוות יבדוק קורים חזקים לחילוץ אנשים. גש לארון הבגדים מימין והתארגן לעבודה.": ["./assets/voices/voice171-c95be1305a80ba.mp3"], "לבשת את בגדי העבודה. עכשיו צריך לקחת את התיק ותג העובד.": ["./assets/voices/voice171-bec3fa02a47293.mp3"], "בתיק יש פנס ותג עובד. המעבדה נמצאת באחוזה ישנה מחוץ לעיר. קיבלת הודעה: ״נפגשים ליד תא 08״. כשאתה מוכן, גש לדלת שבין החלונות ולחץ E.": ["./assets/voices/voice171-4c356ae2bcab55.mp3"], "בדרך לאחוזת המחקר…": ["./assets/voices/voice171-25ae6b620a2a6b.mp3"], "התארגן לעבודה. בגדי העבודה נמצאים בארון, והתיק ותג העובד על השולחן.": ["./assets/voices/voice171-83beb85e23555a.mp3"], "רובוט: בוקר טוב! ברוך הבא לאחוזת המחקר. ד״ר נועה מחכה לך משמאל.": ["./assets/voices/voice171-95b486cefede9a.mp3"], "נועה: אנחנו מנסים ליצור קורי משי לחילוץ אנשים. אמיר יסביר לך איך מודדים את החוזק.": ["./assets/voices/voice171-2060456cd9998e.mp3"], "אמיר: החוט הזה יכול לשאת משקל עצום. אבל העכביש גדל מאז אתמול. מאיה ביקשה לבדוק אותו שוב.": ["./assets/voices/voice171-f0e28fce8ef3e0.mp3"], "מאיה: בדיקה קצרה בלבד. אם הגודל משתנה, עוצרים מיד. יואב הכין את המחשב שמימין.": ["./assets/voices/voice171-03edac59f2a035.mp3"], "יואב: החיישנים מוכנים. עבור לכפתור שליד התא והתחל בדיקת משי.": ["./assets/voices/voice171-b7e5a7ef379d3d.mp3"], "מאיה: רגע… המדידה עולה מהר מדי. תעצרו את ההזנה!": ["./assets/voices/voice171-d8a0bb2b43b0da.mp3"], "המכונית בחניה. גש לדלת הנהג ולחץ E כדי להיכנס.": ["./assets/voices/voice171-7b1f81c0d9ddb0.mp3"], "כריזה: מצב חירום במעבדה. כל אנשי הצוות, להתפנות מיד דרך יציאת החירום!": ["./assets/voices/voice171-17b75150781fc4.mp3"], "יואב: הדלת נסגרת! רגע, הוא עדיין בפנים!": ["./assets/voices/voice171-0f545a1170c0aa.mp3"], "מערכת זיכרון פעילה. תודה שחיברת את הסוללה. אני יחידת תחזוקה 08. בניתי את המסילות, תיקנתי את הדלתות, וזכרתי את מה שהחוקרים העדיפו לשכוח.": ["./assets/voices/voice171-603ec7761ad096.mp3"], "רצינו לעזור לאנשים. קורי עכביש הם קלים וחזקים. החוקרים חלמו על חבלי חילוץ דקים שיצליחו לשאת משקל גדול מתוך בניינים שקרסו.": ["./assets/voices/voice171-838cef2759a725.mp3"], "בתחילת ניסוי 08 היה כאן עכביש קטן. מדדנו כמה משי הוא טווה ובדקנו כל חוט. במשך שבועות הכול נראה רגיל. ואז הביאו דגימה מתחנת המחקר שמתחת לבית.": ["./assets/voices/voice171-13622a6d9ed396.mp3"], "הדגימה שינתה את המשי. החוטים נעשו עבים יותר, אבל העכביש התחיל לגדול. ביקשתי להפסיק. המחשב הישן לא אישר את פקודת הכיבוי, וההזנה נמשכה כל הלילה.": ["./assets/voices/voice171-109f73b52b3d40.mp3"], "הוא למד את התנועות שלנו. בזמן שהחוקרים הביטו לרצפה, הוא טיפס לתקרה. על הזכוכית הופיע סדק ראשון. אחר כך שמענו שלוש נקישות מבפנים.": ["./assets/voices/voice171-3a1e7fc65d8b55.mp3"], "הזכוכית נפרצה. כיביתי את הדלתות כדי לעצור אותו, אבל הוא עבר דרך פתח התחזוקה מעליהן. זו הסיבה שאני אומר לך לבדוק גם את התקרה.": ["./assets/voices/voice171-0f684a75135dad.mp3"], "השוטרים וצוות החילוץ הגיעו בבוקר. הם עקבו אחרי קורים עד למרתף. המצלמה האחרונה הראתה מסדרון ריק, אבל המיקרופון המשיך להקליט שמונה רגליים מתקרבות.": ["./assets/voices/voice171-b1cf328eb45cc9.mp3"], "הצלחתי להוביל כמה מהחוקרים ליציאה. אחרים נשארו בתחנה התחתונה. מאז אף אחד לא ענה לקריאות שלי. את התיעוד שמרתי במחשב ליד היומן הסודי.": ["./assets/voices/voice171-bef4953de95db6.mp3"], "פיצלנו את קוד המעלית לשלושה פתקים: בחדר השינה, בחדר האוכל ובחדר המשחקים. אסוף אותם לתיק וקרא את שלוש השורות לפי הסדר.": ["./assets/voices/voice171-cc52a8a2a24b4f.mp3"], "במעלית יש קומות 1 ו־2, וכפתור עם סימן שאלה. בשבילו צריך כרטיס גישה. השארנו אותו במעבדה בקומה השנייה. מתחת לבית תמצא את מקור הניסוי. אל תתקרב לבור בלי להסתכל.": ["./assets/voices/voice171-5bd203a6377d4d.mp3"], "אם אתה רוצה לצאת, הפנס כבר אצלך. חפש גרזן. שבור את הקרשים בדלת הכניסה. העכביש לא יודע תמיד איפה אתה: פנה מעבר לפינה, התרחק בשקט, והתחבא לפני שיראה אותך.": ["./assets/voices/voice171-ea1deedc92ab4e.mp3"], "הסוללה שלי שוב נחלשת. אשב כאן ואשמור על הארכיון. הכפתור האדום יפתח את הדלת. אם תשמע שלוש נקישות... אל תענה.": ["./assets/voices/voice171-dfa152346d7c19.mp3"], "ברח! אני אעכב אותו!": ["./assets/voices/voice171-b7a03aa843c532.mp3"], "איפה אני? איפה כולם?": ["./assets/voices/voice171-1ea24d3053130f.mp3"], "מגיש החדשות: הבוקר באחוזת המחקר: מדענים יערכו היום את ניסוי 08 בקורי עכביש.": ["./assets/voices/voice171-ef184bdabc4805.mp3"], "מגיש החדשות: הצוות מפתח חבלי חילוץ חזקים וקלים, שיעזרו להציל אנשים ממקומות מסוכנים.": ["./assets/voices/voice171-aa44547c6218b8.mp3"], "מגיש החדשות: החוקרים מסרו שכל הבדיקות יבוצעו בתוך תא זכוכית סגור. נעדכן בהמשך היום.": ["./assets/voices/voice171-c0229661676249.mp3"], "אני: אני רוצה לראות מה אומרים בחדשות.": ["./assets/voices/voice171-7170073568cd6c.mp3"], "אני: לא... לאן אתה לוקח אותי?": ["./assets/voices/voice171-4116923b6f2ee4.mp3"], "אני: זה הבית... אני לא מצליח להישאר ער...": ["./assets/voices/voice171-ca054a521d61e9.mp3"], "אני: אני מצלם…": ["./assets/voices/voice171-8a9f5d5fa0ec40.mp3"], "אני: הוא תפס את הרגליים שלו!": ["./assets/voices/voice171-696be8ce4162d3.mp3"], "רובוט: רוץ למכונית! אני אעצור אותו!": ["./assets/voices/voice171-9e67b911fd69b6.mp3"], "אני: מה יקרה לרובוט? אני צריך לישון.": ["./assets/voices/voice171-d3e691124d20ac.mp3"], "חדשות: התקבל תיעוד יוצא דופן מאחוזת המחקר.": ["./assets/voices/voice171-44b7ab7bae4dcd.mp3"], "חדשות: הרובוט עיכב את העכביש ואפשר לחוקר להימלט.": ["./assets/voices/voice171-97c1a33daa216c.mp3"], "חדשות: גורלו של הרובוט עדיין לא ידוע…": ["./assets/voices/voice171-5c57400403f181.mp3"]};
